from pathlib import Path
from html.parser import HTMLParser
import json,re,pdfplumber,shutil,subprocess
OUT=Path("reports/research/510300_bank_release_vintage_and_nim_definition_probe_v1")
class Body(HTMLParser):
 def __init__(self):super().__init__();self.inside=False;self.lines=[];self.links=[]
 def handle_starttag(self,t,a):
  if t=="body":self.inside=True
  if t=="a":
   d=dict(a)
   if d.get("href"):self.links.append(d["href"])
 def handle_data(self,d):
  if self.inside:self.lines.append(d)
p=json.loads((OUT/"官方正文_data_docId=1221429.json").read_text(encoding="utf-8"))["data"]
b=Body();b.feed(p["docClob"]);text=''.join(b.lines)
(OUT/"2025Q2发布正文_完整提取.txt").write_text(text,encoding="utf-8")
print(json.dumps({"Q2标题":p["docTitle"],"发布日期":p["publishDate"],"正文完整":text,"附件":p["attachmentInfoVOList"],"正文链接":b.links},ensure_ascii=False))
pdf=OUT/"人民银行工作论文_2016_4.pdf";doc=pdfplumber.open(str(pdf))
allpages=[];matches=[];relevant=[]
for i,page in enumerate(doc.pages):
 s=page.extract_text() or "";allpages.append({"pdf_page":i+1,"text":s})
 for term in ["净息差","当季度利息收入","平均贷款利率","表1","表 1","生息资产"]:
  k=s.find(term)
  if k>=0:
   matches.append({"pdf_page":i+1,"term":term,"context":s[max(0,k-350):min(len(s),k+650)]})
 if "当季度利息收入" in s or ("表1" in s.replace(" ","") and "变量" in s):relevant.append(i)
(OUT/"方法论文_全部逐页提取.json").write_text(json.dumps(allpages,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
(OUT/"方法论文_定位片段.json").write_text(json.dumps(matches,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
render=[]
engine=shutil.which("pdftoppm")
for i in sorted(set(relevant)):
 prefix=OUT/("方法页_"+str(i+1))
 if engine:
  subprocess.run([engine,"-f",str(i+1),"-l",str(i+1),"-r","120","-png","-singlefile",str(pdf),str(prefix)],check=True,capture_output=True)
  path=prefix.with_suffix(".png")
 else:
  path=prefix.with_suffix(".png");doc.pages[i].to_image(resolution=120).save(str(path))
 render.append({"pdf_page":i+1,"path":str(path.resolve()),"engine":"pdftoppm" if engine else "pdfplumber"})
(OUT/"方法页渲染定位.json").write_text(json.dumps(render,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
print(json.dumps({"论文总页":len(doc.pages),"封面":allpages[0]["text"][:1500],"方法定位":matches,"渲染":render},ensure_ascii=False))
